urlset:
{%- for file in pages -%}
    {%- if not file.page.is_link and (file.page.abs_url or file.page.canonical_url) -%}
    {%- set url = file.page.canonical_url if file.page.canonical_url else file.page.abs_url -%}
    {%- set path = file.page.abs_url or '' -%}
    {%- if path.endswith('/index.html') -%}
      {%- set path = path[:-10] -%}
    {%- endif -%}
    {#- Determine tier based on URL path -#}
    {%- if path == '/aegis/' or path == '/' or file.page.is_homepage -%}
      {%- set priority = '1.0' -%}
      {%- set changefreq = 'weekly' -%}
    {%- elif '/solutions/' in path or '/comparisons/' in path -%}
      {%- set priority = '0.9' -%}
      {%- set changefreq = 'monthly' -%}
    {%- elif '/research/' in path or '/cookbook/' in path -%}
      {%- set priority = '0.8' -%}
      {%- set changefreq = 'monthly' -%}
    {%- elif '/guides/' in path or '/api/' in path or '/getting-started/' in path -%}
      {%- set priority = '0.7' -%}
      {%- set changefreq = 'monthly' -%}
    {%- elif '/faq/' in path or '/cheatsheet/' in path or '/enterprise/' in path or '/troubleshooting/' in path -%}
      {%- set priority = '0.6' -%}
      {%- set changefreq = 'monthly' -%}
    {%- else -%}
      {%- set priority = '0.5' -%}
      {%- set changefreq = 'monthly' -%}
    {%- endif -%}

         {{ url|e }}
         {% if file.page.update_date %}{{ file.page.update_date }}{% endif %}
         {{ changefreq }}
         {{ priority }}

    {%- endif -%}
{% endfor %}
